import{_ as p,a0 as r,w as l,s as i,ao as u,I as n,x as t,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"學校可以變得敏捷嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"學校可以變得敏捷嗎？ | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"學校可以變得敏捷嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"學校可以變得敏捷嗎？ | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190416 Can schools be agile","title":"學校可以變得敏捷嗎？","tag":"201907","desc":""},"relativePath":"201907/20190416 Can schools be agile.md","filePath":"[post].md"}'),m={name:"201907/20190416 Can schools be agile.md"};function d(f,e,T,g,C,h){const o=r("Link");return l(),i("div",null,[e[15]||(e[15]=u('<h1 id="學校可以變得敏捷嗎" tabindex="-1">學校可以變得敏捷嗎？ <a class="header-anchor" href="#學校可以變得敏捷嗎" aria-label="Permalink to “學校可以變得敏捷嗎？”">​</a></h1><blockquote><p>我們一定不會希望用商業的方式運作我們的學校 —— 但是更加註重持續改進的教育機構是可以讓我們受益的。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/EDUCATION_network.png?itok=ySEHuAQ8" alt=""></p><p>我們都有過那種感覺一件事情“似曾相識”的經歷。在 1980 年代末期我經常會有這種感覺，那時候我剛剛進入工業領域不久。當時正趕上一波組織變革的熱潮，美國製造業在嘗試各種各樣不同的模型，讓企業領導、經理人和像我這樣的工程師重新思考我們應該如何處理質量、成本、創新以及股東價值這樣的問題。我們似乎每一年（有時候更加頻繁）都需要通過學習一本書來找到讓我們更精簡、更扁平、更靈活以及更加能滿足顧客需求的“最佳方案”。</p><p>這裏面的很多方法都帶來了巨大的改進，我至今仍然贊同它們的核心原則。像 John Kotter、Peter Drucker、Edwards Demming 和 Peter Senge 這樣的思想領袖提出的某些思想和策略，還有我們採用的像 Six Sigma 以及在“豐田模式”裏可以找到的一些流程優化方法，對我們改進工作都起到了十分關鍵的作用。</p><p>但是其他人似乎只是在同樣的思想上進行了潤色和調整，然後重新包裝了一下 —— 所以我才會有那種 <em>似曾相識</em> 的感覺。但是當我成為了一名教師之後，我遇到了一個 <em>沒有</em> 給我那種似曾相識的感覺的地方：教育界。事實上我十分驚訝地發現，在我的這個新職業裏，“持續不斷的改進”並 <em>不像</em> 在我之前的職業裏那樣重要了（特別是對於像我這種授課老師職級的人來説）。</p><p>為什麼教育機構很少努力營造一種不斷改進的文化氛圍呢？我能想到幾個原因，在這裏我列舉兩個。</p><h3 id="不再做生產線上的元件" tabindex="-1">不再做生產線上的元件 <a class="header-anchor" href="#不再做生產線上的元件" aria-label="Permalink to “不再做生產線上的元件”">​</a></h3><p>這種不斷改進的文化氛圍遇到的第一個阻礙是，教育界普遍不願意從其它行業借鑑可以為自己所用的思想 —— 特別是來自商界的思想。第二個阻礙是，主導教育界的仍然是一種自上而下的、等級制度森嚴的領導模式。人們往往只能在小範圍內討論這種系統性的、持續的改進方案，比如包括校長、助理校長、學校監管人（LCTT 譯註：美國地方政府下設的一種官職，每個學校監管人管理一定數量的學校，接受學校校長的彙報）等等在內的學校領導和區域領袖。但是一小羣人的參與是遠遠不足以帶來整個組織層面的文化改革的。</p><p>在進一步展開觀點之前，我想強調一下，上面所做的概括一定是存在例外情況的（我自己就見到過很多），不過我覺得任何一個教育界的利益相關者都應該會同意以下兩點基本假設：</p><ol><li>為學生提供高質量的、公平的教育和教學系統的工作所涉及到的任何人都應該將持續不斷的改進作為思維方式裏的重要部分；</li><li>如果學校領導在做決策的時候可以更多地參考那些離學生最近的工作者的意見，那麼學生以及學生所在的社區都將更加受益；</li></ol><p>那麼教育界人士為什麼會傾向於忽視（或者公然地敵視）教育界之外的思想呢？</p><p>比如我過去就曾經提議應該向別的行業借鑑一些思想和靈感來幫助我們更好地迎合學生的需求，並且果然遭到了批評。我經常得到的回應是：“你這是在把我們的學生當成生產線上的元件來對待呀！”但是我們的學生現在就是在被當作生產線上的元件對待，並且已經無以復加了。他們按照被年齡劃分的羣體考入大學，每天根據刺耳的鈴聲的指示去上一節又一節孤立的課程，並且由一些武斷的、強調同一性而不是個性的考試來評判他們的成績。</p><p>很多教育界人士可能不知道，生產線元件這種會讓人想到流水線標準化作業的東西已經不是現代製造業裏的重要組成部分了。得益於上面提到的不斷改進的文化氛圍，現代先進製造業已經可以做到在單個顧客產生需求的時候，以合理的價格有針對性地提供她所需要的商品。如果我們的學校也可以採用這種模式，教師們之間就更可能會進行協作，並且可以基於學生即時的需求和興趣，不斷完善每一個學生獨特的成長和進步路線，而不受時間、課題或者其它傳統規範的限制。</p><p>我並不是要呼籲大家像經營商業一樣經營我們的學校。我所主張的是，用一種清晰而客觀的態度去看待任何行業的任何思想，只要它們有可能幫助我們更好地迎合學生個體的需求。不過，如果想有效率地實現這個目標，我們需要仔細研究這個 100 多年來都停滯不前的領導結構。</p><h3 id="把不斷改進作為努力的目標" tabindex="-1">把不斷改進作為努力的目標 <a class="header-anchor" href="#把不斷改進作為努力的目標" aria-label="Permalink to “把不斷改進作為努力的目標”">​</a></h3><p>有一種説法認為教育和其它行業之間存在着巨大的差異，我雖然贊同這種説法，但同時也相信“重新思考組織和領導結構”這件事情對於任何一個希望對利益相關者負責（並且可以及時作出響應）的主體來説都是適用的。大多數其它行業都已經在重新審視它們傳統的、封閉的、等級森嚴的結構，並且採用可以鼓勵員工基於共有的優秀目標發揮自主性的組織結構 —— 這種組織結構對於不斷改進來説十分關鍵。我們的學校和行政區是時候放開眼界了，而不應該拘泥於只聽到來自內部的聲音，因為它們的用意雖然是好的，但都沒有脱離現有的範式。</p><p>對於任何希望開始或者加速這個轉變過程的學校，我推薦一本很好的書：Jim Whitehurst 的《開放組織》（這不應該讓你感到意外）。這本書不僅可以幫助我們理解教育者如何創造更加開放、覆蓋面更廣的領導領導結構 —— 在這樣的結構下，互相尊重讓人們可以基於實時數據作出更加靈活的決策 —— 並且它所使用的語言風格也和教育者們所習慣使用的奇怪的詞彙庫非常契合（這種詞彙庫簡直是教育者們第二天性)。任何組織都可以借鑑開放組織的思維提供的實用主義方法讓組織成員更加開放：分享想法和資源、擁抱以共同協作為核心的文化、通過快速製作原型來開發創新思維、基於價值（而不是提出者的職級）來評估一個想法，以及創造一種融入到組織 DNA 裏的很強的社區觀念。通過眾包的方式，這樣的開放組織不僅可以從組織內部，也能夠從組織外部收集想法，創造一種可以讓本地化的、以學生為中心的創新蓬勃發展的環境。</p><p>最重要的事情是：在快速變化的未來，我們在過去所做的事情不一定仍然適用了 —— 認清楚這一點對於創造一個不斷改進的文化氛圍是十分關鍵的。對於教育者來説，這意味着我們不能只是簡單地依賴在針對工廠模型發展出來的解決方案和實踐方式了。我們必須從其它行業（比如説非營利組織、軍事、醫療以及商業 —— 沒錯，甚至是商業）裏借鑑數不清的最佳方案，這樣至少應該能讓我們 <em>知道</em> 如何找到讓學生受益最大的辦法。從教育界傳統的陳詞濫調裏超脱出來，才有機會擁有更廣闊的視角。我們可以更好地顧全大局，用更客觀地視角看待我們遇到的問題，同時也知道我們在什麼方面已經做得很不錯。</p><p>通過有意識地借鑑各路思想 —— 從一年級教師到紐約時報上最新的商業、管理、領導力暢銷書 —— 我們可以更好地發掘和運用校內人才，以幫助我們克服阻礙了我們的學校和區域進步的制度裏的惰性。</p><p>堅持不懈地追求不斷改進這件事情，不應該只侷限於那種努力在一個全球化的、創新的經濟環境中爭取競爭力的機構，或者是負責運營學校的少數幾個人。當機構裏的每一個人都能不斷思考怎樣才能讓今天比昨天做得更好的時候，這就是一個擁有優秀的文化氛圍的機構。這種非常有注重協作性和創新的文化氛圍，正是我們希望在這些負責改變年輕人命運的機構身上看到的。</p><p>我非常期待，有朝一日我能在學校裏感受到這種精神，然後微笑着對自己説：“這種感覺多麼似曾相識啊。”</p><hr>',23)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),s(o,{href:"https://opensource.com/open-organization/19/4/education-culture-agile"},{default:a(()=>[...e[0]||(e[0]=[t("https://opensource.com/open-organization/19/4/education-culture-agile",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),s(o,{href:"https://opensource.com/users/engineerteacher/users/ke4qqq/users/n8chz/users/don-watkins"},{default:a(()=>[...e[2]||(e[2]=[t("Ben Owens",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),s(o,{href:"https://github.com/chen-ni"},{default:a(()=>[...e[4]||(e[4]=[t("chen-ni",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const L=p(m,[["render",d]]);export{k as __pageData,L as default};
